public boolean fieldHandled(str _fieldName)
{
    return subStr(_fieldName,1,9) == TFMConstants::variables();
}

public void handleField(str _value, FormGroupControl _fgc)
{

    ListEnumerator          lEnum = TFMHelper::strSplit(_value, '[;]').getEnumerator();
    List                    keyAndValue;
    ListEnumerator          kvEnum;
    str                     key, value;
    while (lEnum.moveNext())
    {
        keyAndValue = TFMHelper::strSplit(lEnum.current(),'[=]');
        if (keyAndValue.elements() == 2)
        {
            kvEnum = keyAndValue.getEnumerator();
            kvEnum.moveNext();
            key = kvEnum.current();
            kvEnum.moveNext();
            value = kvEnum.current();
            this.makeField(_fgc, key, value);
        }
    }


}

protected void makeField(FormGroupControl _fgc, str _key, str _value)
{
    str                     key = strReplace(_key, TFMConstants::ItemNumber(), extendedTypeStr(ItemId));
    FormStringControl       fsc = _fgc.addControl(FormControlType::String,TFMConstants::variables()+'_'+key);

    if (extendedTypeName2Id(key))
    {

        fsc.extendedDataType(extendedTypeName2Id(key));
    }
    else
    {
        fsc.label(key);
    }

    fsc.text(_value);
}
